<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
const props = defineProps({ view: { type: String, required: true } });
const hiddenCategories = new Set(['英文打字', '拼音打字']);
const categoryOrder = ['校园生活','成长励志','生活随笔','科技阅读','一分钟挑战','英文挑战','拼音挑战','英文打字','拼音打字'];
const modeCategories = new Set(['一分钟挑战','英文挑战','拼音挑战']);
function groupCategories(items, includeHidden = false) {
  const sorted = [...new Set(items)].sort((a,b) => { const rank = x => { const i=categoryOrder.indexOf(x); return i<0 ? categoryOrder.length : i; }; return rank(a)-rank(b) || a.localeCompare(b,'zh-Hans-CN'); });
  const groups = [
    {label:'练习文章',items:sorted.filter(x=>!modeCategories.has(x)&&!hiddenCategories.has(x))},
    {label:'模式专用（挑战 / 竞速）',items:sorted.filter(x=>modeCategories.has(x))}
  ];
  if(includeHidden) groups.push({label:'前台未使用（历史文章）',items:sorted.filter(x=>hiddenCategories.has(x))});
  return groups.filter(group=>group.items.length);
}
const passageFilterGroups = computed(() => groupCategories(categories.value, true));
const passageEditGroups = computed(() => {
  const groups=groupCategories(categories.value);
  if(form.id && form.category && !groups.some(group=>group.items.includes(form.category))) {
    groups.unshift({label:'当前文章分类',items:[form.category]});
  }
  return groups;
});
const title = computed(() => ({passages:'练习文章',assignments:'教学任务',progress:'学习进步',scores:'竞速成绩'}[props.view] || '教学管理'));
const modeNames = { all:'所有课程', beginner:'新手入门', 'english-word':'英文单词', 'english-phrase':'英文语句', 'english-article':'英文文章', 'pinyin-syllable':'拼音音节', 'pinyin-word':'拼音词组', 'pinyin-article':'拼音文章' };
const displayMode = mode => ({ ...modeNames, battle:'占领战', boss:'全班打 Boss', race:'打字赛车', rhythm:'节奏连击', runner:'遗迹逃亡', challenge:'一分钟挑战', 'competition-personal':'竞速比赛', 'competition-team':'团队比赛' })[mode] || mode;
const trendPoints = computed(() => { const data=progressDetail.value?.daily||[]; if(!data.length)return ''; const speeds=data.map(item=>Number(item.speed)||0), min=Math.max(0,Math.min(...speeds)-10), max=Math.max(20,...speeds); return data.map((item,i)=>`${46+(data.length===1?308:i*616/(data.length-1))},${20+180*(1-((Number(item.speed)||0)-min)/Math.max(1,max-min))}`).join(' '); });
const q = reactive({ q:'', category:'', classId:'', range:'', isActive:'', mode:'', sort:'speedChange', order:'desc' });
const rows = ref([]), total = ref(0), page = ref(1), pageSize = ref(20), categories = ref([]), scoreCategories = ref([]), classes = ref([]), students = ref([]), overview = ref(null), error = ref(''), loading = ref(false), busy = ref(false), dialog = ref(''), detail = ref(null), generating = ref(false);
const form = reactive({}), progressDetail = ref(null); let requestId=0;
const fmt = value => { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value) : d.toLocaleString('zh-CN', {hour12:false}); };
const filters = () => Object.fromEntries(Object.entries(q).filter(([,v]) => v !== '' && v != null));
async function api(path, options={}) { const response = await fetch(path,{...options,signal:options.signal||AbortSignal.timeout(10000),headers:{'Content-Type':'application/json',...(options.headers||{})}}); const data=await response.json().catch(()=>({})); if(!response.ok) { if(response.status===401) window.dispatchEvent(new Event('admin-session-expired')); throw new Error(data.message || (response.status===401 ? '登录已过期，请重新登录' : '请求失败，请稍后重试')); } return data; }
async function load() {
  const id=++requestId, v=props.view; loading.value=true; error.value='';
  try {
    const params = new URLSearchParams({ ...filters(), page:String(page.value), pageSize:String(pageSize.value) });
    const url = {passages:'/api/admin/passages', assignments:'/api/admin/assignments', progress:'/api/admin/progress/students', scores:'/api/admin/scores'}[v];
    if (!url) return;
    const data=await api(`${url}?${params}`); if(id!==requestId) return;
    rows.value=data.rows||[]; total.value=data.total||0; page.value=data.page||1;
    if(v==='passages') categories.value=data.categories||[];
    if(v==='progress') { const result=await api('/api/admin/progress/overview'); if(id===requestId) overview.value=result; }
  } catch(e){ if(id===requestId) error.value=e.message; } finally { if(id===requestId) loading.value=false; }
}
async function loadOptions() {
  try {
    const data=await api('/api/admin/classes?all=true'); classes.value=(data.rows||[]).filter(x=>x.isActive);
    const cats=await api('/api/admin/score-categories'); scoreCategories.value=cats.categories||[];
  } catch(e) { error.value=e.message; }
}
async function loadStudents(){ const first=await api('/api/admin/users?page=1&pageSize=50'); let all=[...(first.rows||[])]; for(let i=2;i<=(first.pages||1);i++) { const result=await api(`/api/admin/users?page=${i}&pageSize=50`); all.push(...(result.rows||[])); } students.value=all.filter(x=>x.isActive); }
function resetQuery(){ Object.assign(q,{q:'',category:'',classId:'',range:'',isActive:'',mode:'',sort:'speedChange',order:'desc'}); page.value=1; rows.value=[]; total.value=0; }
function search(){page.value=1;load();}
function sortChange({prop,order}) { q.sort=prop==='displayName'?'name':(prop||'speedChange'); q.order=order==='ascending'?'asc':'desc';search(); }
function resetForm(value) { for(const k of Object.keys(form)) delete form[k]; Object.assign(form,value); }
function editPassage(item) { resetForm(item ? {...item,isActive:!!item.isActive} : {title:'',category:'',content:'',isActive:true}); dialog.value='passage'; }
async function savePassage(){ if(!form.title?.trim() || !form.category || form.content?.trim().length<20) return ElMessage.warning('请填写标题、分类和至少 20 个字符的正文'); busy.value=true; try { await api(form.id?`/api/admin/passages/${form.id}`:'/api/admin/passages',{method:form.id?'PUT':'POST',body:JSON.stringify({title:form.title,category:form.category,content:form.content,isActive:form.isActive})}); dialog.value=''; ElMessage.success('文章已保存'); await load(); } catch(e){ElMessage.error(e.message)} finally{busy.value=false;} }
async function generate(){ if(form.content?.trim()) { try { await ElMessageBox.confirm('当前正文将被覆盖，继续生成吗？','生成文章'); } catch{return;} } generating.value=true; try {const data=await api('/api/admin/passages/generate',{method:'POST',body:JSON.stringify({title:form.title.trim(),category:form.category,length:400}),signal:AbortSignal.timeout(90000)});form.title=data.title||form.title;form.content=data.content||'';ElMessage.success('请检查生成内容后保存');} catch(e){ElMessage.error(e.message)} finally{generating.value=false} }
async function removePassage(row){try{await ElMessageBox.confirm(`确定删除《${row.title}》吗？历史成绩会保留。`,'删除文章',{type:'warning'});await api(`/api/admin/passages/${row.id}`,{method:'DELETE'});ElMessage.success('文章已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close') ElMessage.error(e.message||'删除失败')} }
async function editAssignment(item){ try { await Promise.all([loadOptions(),loadStudents()]); resetForm(item ? {...item,studentIds:(item.studentIds||[]).map(Number),classId:item.classId||null,dueAt:item.dueAt||null} : {title:'',description:'',mode:'all',lessonTitle:'',audience:'all',classId:null,studentIds:[],targetAccuracy:null,targetSpeed:null,dueAt:null});dialog.value='assignment'; }catch(e){ElMessage.error(e.message)} }
async function saveAssignment(){ if(!form.title?.trim()) return ElMessage.warning('请填写任务名称'); if(form.audience==='class'&&!form.classId) return ElMessage.warning('请选择班级'); if(form.audience==='selected'&&!form.studentIds?.length) return ElMessage.warning('请选择学生'); busy.value=true; try {const payload={title:form.title,description:form.description,mode:form.mode,lessonTitle:form.lessonTitle,audience:form.audience,classId:form.audience==='class'?form.classId:null,studentIds:form.audience==='selected'?form.studentIds:[],targetAccuracy:form.targetAccuracy,targetSpeed:form.targetSpeed,dueAt:form.dueAt||null};await api(form.id?`/api/admin/assignments/${form.id}`:'/api/admin/assignments',{method:form.id?'PUT':'POST',body:JSON.stringify(payload)});dialog.value='';ElMessage.success('任务已保存');await load();}catch(e){ElMessage.error(e.message)}finally{busy.value=false} }
async function toggle(row){ try{await api(`/api/admin/assignments/${row.id}/status`,{method:'PATCH',body:JSON.stringify({isActive:!row.isActive})});ElMessage.success(row.isActive?'任务已停用':'任务已启用');await load()}catch(e){ElMessage.error(e.message)} }
async function showProgress(row){try{progressDetail.value=await api(`/api/admin/progress/students/${row.id}`);dialog.value='progress';}catch(e){ElMessage.error(e.message)} }
async function removeScore(row){try{await ElMessageBox.confirm(`确定删除 ${row.nickname} 的 ${row.score} 字成绩吗？`,'删除成绩',{type:'warning'});await api(`/api/admin/scores/${row.id}`,{method:'DELETE'});ElMessage.success('成绩已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close') ElMessage.error(e.message||'删除失败')} }
async function exportWorkbook(rows, name, sheet) {if(!rows.length) return ElMessage.warning('当前筛选没有可导出的记录');const XLSX = await import('xlsx'); const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows),sheet);XLSX.writeFile(book,`${name}-${new Date().toLocaleDateString('zh-CN').replaceAll('/','-')}.xlsx`);ElMessage.success(`已导出 ${rows.length} 条记录`);}
async function exportRows(){try{const params=new URLSearchParams(filters());if(props.view==='scores'){const d=await api(`/api/admin/scores/export?${params}`);await exportWorkbook((d.rows||[]).map(x=>({'学生姓名':x.nickname,'学号':x.studentId||'','班级':x.className||'未分班','登录账号':x.username||'','正确字数':x.score,'正确率百分比':x.accuracy,'错字数':x.wrongChars,'挑战文章':x.passageTitle||'文章已删除','提交时间':fmt(x.createdAt)})),'竞速成绩','竞速成绩');}else{if(!q.classId)return ElMessage.warning('请先选择具体班级或待分班');const d=await api(`/api/admin/progress/weekly?${params}`);await exportWorkbook((d.rows||[]).map(x=>({'周开始':x.weekStart,'周结束':x.weekEnd,'班级':x.className,'学生姓名':x.displayName,'登录账号':x.username,'学号':x.studentId,'训练次数':x.sessions,'活跃天数':x.activeDays,'练习时长小时':x.durationHours,'正确字数':x.correctChars,'错误字数':x.wrongChars,'总字数':x.totalChars,'平均速度字每分':x.averageSpeed,'最高速度字每分':x.bestSpeed,'准确率百分比':x.accuracy,'训练模式':(x.modes||'').split('、').map(displayMode).join('、'),'最近训练':fmt(x.latestAt)})),'学生每周打字情况','每周打字情况');}}catch(e){ElMessage.error(e.message)} }
watch(()=>props.view,()=>{ resetQuery(); load(); loadOptions(); }); onMounted(()=>{load();loadOptions()});
</script>
<template>
  <section class="teaching-page">
    <header class="teaching-heading"><div><h1>{{ title }}</h1><p>管理课堂内容与训练情况</p></div><div><el-button v-if="view==='passages'" type="primary" @click="editPassage(null)">新增文章</el-button><el-button v-if="view==='assignments'" type="primary" @click="editAssignment(null)">发布任务</el-button><el-button v-if="view==='scores'||view==='progress'" @click="exportRows">{{ view==='scores'?'导出成绩':'导出周报' }}</el-button><el-button @click="load" :loading="loading">刷新</el-button></div></header>
    <div v-if="view==='progress' && overview" class="teaching-summary"><span>已监测学生 <b>{{ overview.monitoredStudents }}</b></span><span>有进步学生 <b>{{ overview.improvingStudents }}</b></span><span>平均速度变化 <b>{{ overview.averageSpeedChange }}</b></span><span>近 7 天训练 <b>{{ overview.sessionsLast7Days }}</b></span></div>
    <section class="teaching-panel"><form class="teaching-filters" @submit.prevent="search"><el-input v-model="q.q" clearable :placeholder="view==='passages'?'搜索标题或分类':view==='assignments'?'搜索任务名称或说明':'搜索学生姓名或账号'" aria-label="关键词"/>
      <el-select v-if="view==='passages'" v-model="q.category" clearable placeholder="全部分类" aria-label="分类" @change="search"><el-option-group v-for="group in passageFilterGroups" :key="group.label" :label="group.label"><el-option v-for="x in group.items" :key="x" :label="x" :value="x"/></el-option-group></el-select><el-select v-else-if="view==='scores'" v-model="q.category" clearable placeholder="全部分类" aria-label="分类"><el-option v-for="x in scoreCategories" :key="x" :label="x" :value="x"/></el-select>
      <el-select v-if="view==='progress'||view==='scores'" v-model="q.classId" clearable placeholder="全部班级" aria-label="班级"><el-option label="待分班" value="unassigned"/><el-option v-for="x in classes" :key="x.id" :label="x.term?`${x.name} · ${x.term}`:x.name" :value="String(x.id)"/></el-select>
      <el-select v-if="view==='scores'" v-model="q.range" clearable placeholder="全部时间" aria-label="时间"><el-option label="今天" value="today"/><el-option label="近 7 天" value="7d"/><el-option label="近 30 天" value="30d"/></el-select>
      <template v-if="view==='assignments'"><el-select v-model="q.isActive" clearable placeholder="全部状态" aria-label="任务状态"><el-option label="进行中" value="1"/><el-option label="已停用" value="0"/></el-select><el-select v-model="q.mode" clearable placeholder="全部课程" aria-label="课程"><el-option v-for="(name,key) in modeNames" :key="key" :label="name" :value="key"/></el-select></template><el-button type="primary" native-type="submit">查询</el-button></form>
      <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
      <el-table v-if="view==='passages'" v-loading="loading" :data="rows" height="100%" empty-text="没有找到文章"><el-table-column prop="title" label="标题" min-width="180"/><el-table-column prop="category" label="分类" min-width="120"/><el-table-column label="字数" width="80"><template #default="{row}">{{ Array.from(row.content||'').length }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{ row.isActive?'使用中':'已停用' }}</template></el-table-column><el-table-column label="更新时间" min-width="160"><template #default="{row}">{{ fmt(row.updatedAt) }}</template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="editPassage(row)">编辑</el-button><el-button link type="danger" @click="removePassage(row)">删除</el-button></template></el-table-column></el-table>
      <el-table v-else-if="view==='assignments'" v-loading="loading" :data="rows" height="100%" empty-text="暂无任务"><el-table-column prop="title" label="任务" min-width="160"/><el-table-column label="课程" min-width="130"><template #default="{row}">{{ modeNames[row.mode]||row.mode }} {{ row.lessonTitle }}</template></el-table-column><el-table-column label="对象" min-width="130"><template #default="{row}">{{ row.audience==='class' ? `班级：${row.className||'已删除'}` : row.audience==='selected'?'指定学生':'全部学生' }}</template></el-table-column><el-table-column label="目标" min-width="150"><template #default="{row}">{{ [Number(row.targetAccuracy) ? `准确率 ${row.targetAccuracy}%` : '', Number(row.targetSpeed) ? `速度 ${row.targetSpeed} 字/分` : ''].filter(Boolean).join(' / ') || '完成练习' }}</template></el-table-column><el-table-column label="完成情况" min-width="130"><template #default="{row}">{{row.completedCount}} / {{row.targetCount}} 人 ({{row.completionRate}}%)</template></el-table-column><el-table-column label="截止时间" min-width="160"><template #default="{row}">{{ row.dueAt?fmt(row.dueAt):'不限时' }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}">{{row.isActive?'进行中':'已停用'}}</template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="editAssignment(row)">编辑</el-button><el-button link @click="toggle(row)">{{row.isActive?'停用':'启用'}}</el-button></template></el-table-column></el-table>
      <el-table v-else-if="view==='progress'" v-loading="loading" :data="rows" height="100%" @sort-change="sortChange"><el-table-column prop="displayName" label="学生" min-width="120" sortable="custom"/><el-table-column prop="sessions" label="训练次数" width="110" sortable="custom"/><el-table-column prop="dailyHours" label="日均小时" width="110" sortable="custom"/><el-table-column prop="firstSpeed" label="首次速度" width="110" sortable="custom"/><el-table-column prop="recentSpeed" label="近期速度" width="110" sortable="custom"/><el-table-column prop="speedChange" label="速度变化" width="110" sortable="custom"/><el-table-column prop="accuracyChange" label="准确率变化" width="130" sortable="custom"/><el-table-column label="最近训练" min-width="160"><template #default="{row}">{{fmt(row.latestAt)}}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showProgress(row)">详情</el-button></template></el-table-column></el-table>
      <el-table v-else-if="view==='scores'" v-loading="loading" :data="rows" height="100%"><el-table-column label="学生账号" min-width="150"><template #default="{row}"><strong>{{ row.nickname }}</strong><small class="score-account">{{ row.username ? `@${row.username}` : '旧版访客成绩' }}</small></template></el-table-column><el-table-column label="班级" min-width="130"><template #default="{row}">{{ row.className || '未分班' }}</template></el-table-column><el-table-column prop="score" label="正确字数" width="100"/><el-table-column label="正确率" width="100"><template #default="{row}">{{ row.accuracy }}%</template></el-table-column><el-table-column prop="wrongChars" label="错字" width="80"/><el-table-column label="挑战文章" min-width="190" show-overflow-tooltip><template #default="{row}">{{ row.passageTitle || '文章已删除' }}</template></el-table-column><el-table-column label="提交时间" min-width="160"><template #default="{row}">{{fmt(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="danger" @click="removeScore(row)">删除</el-button></template></el-table-column></el-table>
      <div class="teaching-pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,50]" :total="total" layout="sizes, prev, pager, next" @size-change="page=1; load()" @current-change="load"/></div>
    </section>
    <el-dialog :model-value="dialog==='passage'" @update:model-value="v=>{if(!v) dialog=''}" :title="form.id?'编辑文章':'新增文章'" width="min(720px, 94vw)"><el-form label-position="top"><el-form-item label="文章标题"><el-input v-model="form.title" maxlength="60"/></el-form-item><el-form-item label="文章分类"><el-select v-model="form.category" filterable placeholder="请选择分类"><el-option-group v-for="group in passageEditGroups" :key="group.label" :label="group.label"><el-option v-for="x in group.items" :key="x" :label="x" :value="x"/></el-option-group></el-select></el-form-item><el-form-item label="练习正文"><el-input v-model="form.content" type="textarea" :rows="10" maxlength="2000" show-word-limit/></el-form-item><el-button :disabled="!form.title?.trim()||!form.category||hiddenCategories.has(form.category)" :loading="generating" @click="generate">AI 生成文章</el-button><p>{{ hiddenCategories.has(form.category) ? '该分类前台未使用，请手工编辑或选择其他分类。' : form.category === '英文挑战' ? '将生成英文文章，请检查后保存。' : '请检查生成内容后再保存。' }}</p><el-switch v-model="form.isActive" active-text="立即启用"/></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="savePassage">保存</el-button></template></el-dialog>
    <el-dialog :model-value="dialog==='assignment'" @update:model-value="v=>{if(!v) dialog=''}" :title="form.id?'编辑任务':'发布任务'" width="min(720px, 94vw)"><el-form label-position="top"><div class="teaching-form-grid"><el-form-item label="任务名称"><el-input v-model="form.title" maxlength="80"/></el-form-item><el-form-item label="课程类型"><el-select v-model="form.mode"><el-option v-for="(name,key) in modeNames" :key="key" :label="name" :value="key"/></el-select></el-form-item><el-form-item label="指定练习（可选）"><el-input v-model="form.lessonTitle" maxlength="80"/></el-form-item><el-form-item label="任务对象"><el-select v-model="form.audience"><el-option label="全部已启用学生" value="all"/><el-option label="指定班级" value="class"/><el-option label="指定学生" value="selected"/></el-select></el-form-item><el-form-item v-if="form.audience==='class'" label="选择班级"><el-select v-model="form.classId" filterable><el-option v-for="x in classes" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item v-if="form.audience==='selected'" label="选择学生"><el-select v-model="form.studentIds" multiple filterable><el-option v-for="x in students" :key="x.id" :label="`${x.displayName}（${x.username}）`" :value="x.id"/></el-select></el-form-item><el-form-item label="目标准确率（%）"><el-input-number v-model="form.targetAccuracy" :min="0" :max="100"/></el-form-item><el-form-item label="目标速度（字/分）"><el-input-number v-model="form.targetSpeed" :min="0" :max="1000"/></el-form-item><el-form-item label="截止时间（可选）"><el-date-picker v-model="form.dueAt" type="datetime" value-format="x" placeholder="不限时"/></el-form-item></div><el-form-item label="任务说明"><el-input v-model="form.description" type="textarea" maxlength="300"/></el-form-item></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="saveAssignment">保存</el-button></template></el-dialog>
    <el-dialog :model-value="dialog==='progress'" @update:model-value="v=>{if(!v) dialog=''}" title="学习进步详情" class="progress-detail-dialog" top="4vh" width="min(720px, 94vw)"><template v-if="progressDetail"><h3>{{progressDetail.student.displayName}}</h3><p>共 {{progressDetail.student.sessions}} 次训练 · 近期速度 {{progressDetail.student.recentSpeed}} 字/分</p><p>实际训练 {{progressDetail.student.activeDays}} 天 · 日均 {{progressDetail.student.dailyHours}} 小时 · 速度变化 {{progressDetail.student.speedChange ?? '训练不足'}} 字/分</p><div class="teaching-mode-tags"><el-tag v-for="(count, mode) in progressDetail.student.modes" :key="mode">{{ displayMode(mode) }} {{count}} 次</el-tag></div><h4>近期速度趋势</h4><svg v-if="trendPoints" viewBox="0 0 708 230" class="teaching-trend" role="img" aria-label="近期打字速度变化趋势"><line x1="46" y1="200" x2="662" y2="200" stroke="#ccdcd2"/><line x1="46" y1="20" x2="46" y2="200" stroke="#ccdcd2"/><polyline :points="trendPoints" fill="none" stroke="#229b64" stroke-width="3"/><text x="46" y="222" fill="#61766b" font-size="12">{{progressDetail.daily[0].date}}</text><text x="662" y="222" text-anchor="end" fill="#61766b" font-size="12">{{progressDetail.daily.at(-1).date}}</text></svg><p v-else>暂无可绘制的训练趋势。</p><el-table :data="progressDetail.daily"><el-table-column prop="date" label="日期"/><el-table-column prop="speed" label="速度"/><el-table-column prop="accuracy" label="准确率"/><el-table-column prop="sessions" label="训练次数"/></el-table><h4>最近训练</h4><el-table :data="progressDetail.recent.slice(0,8)"><el-table-column label="模式"><template #default="{row}">{{displayMode(row.mode)}}</template></el-table-column><el-table-column prop="speed" label="速度"/><el-table-column prop="accuracy" label="准确率"/><el-table-column label="时间"><template #default="{row}">{{fmt(row.completedAt)}}</template></el-table-column></el-table></template></el-dialog>
  </section>
</template>
